"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["99200"],{12782(e){e.exports=JSON.parse('{"id":"V4-082","slug":"sustainability-report","term":"Sustainability Report","also_known_as":[],"difficulty":"Intermediate","definition":"A sustainability report is a report published by a company describing its environmental, social and governance performance and impacts, such as its carbon emissions, use of resources, treatment of employees and community activities.","explanation":["Sustainability reports, also called ESG reports or corporate responsibility reports, give investors, customers, employees and other stakeholders information about how a company manages issues beyond financial performance.","They typically cover greenhouse gas emissions, energy and water use, waste, workforce diversity, health and safety, human rights in supply chains, community engagement and governance practices, often with targets and progress over time.","For example, a retailer\u2019s sustainability report might disclose its total emissions, its target to reach net zero, the share of its products sourced responsibly and the gender balance of its leadership.","Sustainability reporting has moved from mostly voluntary to increasingly required. Frameworks and standards include the Global Reporting Initiative, the ISSB Standards and, in the European Union, the European Sustainability Reporting Standards under the Corporate Sustainability Reporting Directive, whose scope has been reduced. Concerns about greenwashing have increased demands for consistent, comparable and independently assured information."],"note":"","total":1725,"prev":{"slug":"sustainability-linked-loan","term":"Sustainability-Linked Loan"},"next":{"slug":"sustainable-growth-rate","term":"Sustainable Growth Rate"}}')}}]);